func LanguageTargetHash(language string) (string, string, bool) {
	p, ok := languageProfiles[language]
	return p.Source, p.Target, ok
}
func PatchLanguage(language string, source []byte) ([]byte, error) {
	p, ok := languageProfiles[language]
	if !ok {
		return nil, fmt.Errorf("unsupported language %s", language)
	}
	if SHA(source) != p.Source {
		return nil, fmt.Errorf("language %s source SHA mismatch: %s", language, SHA(source))
	}
	lines := bytes.Split(source, []byte(p.EOL))
	count := 0
	for i, row := range lines {
		split := bytes.IndexByte(row, '=')
		if split < 1 {
			return nil, fmt.Errorf("malformed language file")
		}
		if newHex, found := p.Updates[string(row[:split])]; found {
			val := bfromhex(newHex)
			lines[i] = append(append([]byte(nil), row[:split+1]...), val...)
			count++
		}
	}
	if count != len(p.Updates) {
		return nil, fmt.Errorf("missing translations: %d/%d", count, len(p.Updates))
	}
	target := bytes.Join(lines, []byte(p.EOL))
	if SHA(target) != p.Target {
		return nil, fmt.Errorf("language target SHA mismatch")
	}
	return target, nil
}
